mapper.update:
UPDATE adm_auth_menu
   SET use_yn     = 'N',
       updated_at = SYSTIMESTAMP,
       updated_by = #{updated_by}
 WHERE auth_group_seq = #{auth_group_seq}

UPDATE adm_auth_menu
   SET perm_lvl   = 0,
       use_yn     = 'N',
       updated_at = SYSTIMESTAMP,
       updated_by = #{updated_by}
 WHERE auth_group_seq = #{auth_group_seq}
   AND menu_seq = #{menu_seq}

UPDATE adm_auth_menu
   SET perm_lvl   = #{perm_lvl},
       use_yn     = #{use_yn},
       updated_at = SYSTIMESTAMP,
       updated_by = #{updated_by}
 WHERE auth_group_seq = #{auth_group_seq}
   AND menu_seq = #{menu_seq}
